  document.querySelector('#undo-form button').click();await savedFiles(saved.original);await ready();document.querySelector('#redo-form button').click();await savedFiles(grid.files);await ready();const gridAudio=await render('grid');checks.push('a retained grid take updates two owned files with version 4 recovery and one exact Undo/Redo');
  document.querySelector('#undo-form button').click();await savedFiles(saved.original);await ready();
