  const send=value=>input.enqueue(new TextEncoder().encode(JSON.stringify(value)+'\n'));let sequence=0;const position=tick=>({epoch,tick,valid:true,playing:true}),midi=(tick,...data)=>send({type:'message',device:'source-surface',group:0,length:data.length,data:[...data,...Array(3-data.length).fill(0)],position:position(tick),hostNanos:1000000000+(++sequence)*1000000,timeSource:'source'});
  send({type:'devices',inputs:[{id:'source-surface',name:'Synthetic source recorder',epoch:1}],position:position(3840)});midi(3857,0x92,60,103);await wait(()=>messages.some(m=>m.type==='note'&&m.on==='true'),'live note acknowledged');
  await wait(async()=>{const local=JSON.parse(sessionStorage.getItem('cicada.note-take')||'null');if(!local?.id)return false;const r=await fetch('/api/note-recovery/'+local.id);if(!r.ok)return false;const d=await r.json();return d.version===4&&d.sourceRevision===captureView.sourceRevision;},'capture project receipt checkpointed');
